/**
 * Capitalizes the first letter of each word in a sentence.
 *
 * @param {string} sentence The input string to be capitalized.
 * @returns {string} The sentence with the first letter of each word capitalized.
 */
function capitalizeWords(sentence) {
  // 1. Handle edge cases: null, undefined, or empty string
  if (!sentence) {
    return "";
  }

  // 2. Convert the entire sentence to lowercase first to ensure consistency
  // (This handles cases where the input might be "tHis is a tEsT")
  const lowerCaseSentence = sentence.toLowerCase();

  // 3. Split the sentence into an array of words using space as the delimiter
  const words = lowerCaseSentence.split(' ');

  // 4. Map over the array of words, capitalizing the first letter of each word
  const capitalizedWords = words.map(word => {
    // Handle empty strings that might result from multiple spaces ("hello  world")
    if (word.length === 0) {
      return "";
    }
    // Get the first character and convert it to uppercase
    const firstLetter = word.charAt(0).toUpperCase();
    // Get the rest of the word (from the second character onwards)
    const restOfWord = word.slice(1);
    // Combine them
    return firstLetter + restOfWord;
  });

  // 5. Join the array of capitalized words back into a single string with spaces
  const result = capitalizedWords.join(' ');

  return result;
}

