public class StringUtils {

    /**
     * Counts the number of vowels (a, e, i, o, u, case-insensitive) in a given string.
     *
     * @param str The input string to analyze.
     * @return The total count of vowels in the string.
     */
    public static int countVowels(String str) {
        // Handle null or empty string case immediately
        if (str == null || str.isEmpty()) {
            return 0;
        }

        int vowelCount = 0;

        // Convert the entire string to lowercase to simplify the checking process
        String lowerCaseStr = str.toLowerCase();

        // Iterate through each character of the string
        for (int i = 0; i < lowerCaseStr.length(); i++) {
            char ch = lowerCaseStr.charAt(i);

            // Check if the current character is a vowel
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                vowelCount++;
            }
        }

        return vowelCount;
    }

    // --- Alternative implementation using Regular Expressions (More concise) ---
    public static int countVowelsRegex(String str) {
        if (str == null) {
            return 0;
        }
        // The regex "[aeiouAEIOU]" matches any vowel, and the '+' means one or more occurrences.
        // We use the pattern to find all matches and then count them.
        // Note: Since we are using the case-insensitive flag (or converting to lower case first),
        // we can simplify the pattern.
        return str.toLowerCase().chars() // Get an IntStream of character codes
                   .filter(c -> c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
                   .count();
    }


    public static void main(String[] args) {
        String test1 = "Hello World"; // e, o, o (3)
        String test2 = "Programming is Awesome"; // o, a, i, i, A, e, o, e (8)
        String test3 = "Rhythm"; // 0
        String test4 = ""; // 0
        String test5 = null; // 0

        System.out.println("--- Iterative Method ---");
        System.out.println("'" + test1 + "': " + countVowels(test1)); // Expected: 3
        System.out.println("'" + test2 + "': " + countVowels(test2)); // Expected: 8
        System.out.println("'" + test3 + "': " + countVowels(test3)); // Expected: 0
        System.out.println("Empty String: " + countVowels(test4)); // Expected: 0
        System.out.println("Null String: " + countVowels(test5)); // Expected: 0

        System.out.println("\n--- Regex Method ---");
        System.out.println("'" + test1 + "': " + countVowelsRegex(test1)); // Expected: 3
        System.out.println("'" + test2 + "': " + countVowelsRegex(test2)); // Expected: 8
    }
}
